// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
ainst::FExtpkg* ainst::extpkg_InsertMaybe(const dev::Extpkg &value) {
    ainst::FExtpkg *row = &extpkg_Alloc(); // if out of memory, process dies. if input error, return NULL.
    extpkg_CopyIn(*row,const_cast<dev::Extpkg&>(value));
    bool ok = extpkg_XrefMaybe(*row); // this may return false
    if (!ok) {
        extpkg_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- ainst.FDb.extpkg.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* ainst::extpkg_AllocMem() {
    u64 new_nelems     = _db.extpkg_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    ainst::FExtpkg*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.extpkg_lary[bsr];
        if (!lev) {
            lev=(ainst::FExtpkg*)algo_lib::malloc_AllocMem(sizeof(ainst::FExtpkg) * (u64(1)<<bsr));
            _db.extpkg_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.extpkg_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- ainst.FDb.extpkg.RemoveAll
// Remove all elements from Lary
void ainst::extpkg_RemoveAll() {
    for (u64 n = _db.extpkg_n; n>0; ) {
        n--;
        extpkg_qFind(u64(n)).~FExtpkg(); // destroy last element
        _db.extpkg_n = i64(n);
    }
}

// --- ainst.FDb.extpkg.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void ainst::extpkg_RemoveLast() {
    u64 n = _db.extpkg_n;
    if (n > 0) {
        n -= 1;
        extpkg_qFind(u64(n)).~FExtpkg();
        _db.extpkg_n = i64(n);
    }
}

