// --- ainst.FDb.zd_sel_extpkg.Insert
// Insert row into linked list. If row is already in linked list, do nothing.
void ainst::zd_sel_extpkg_Insert(ainst::FExtpkg& row) {
    if (!zd_sel_extpkg_InLlistQ(row)) {
        ainst::FExtpkg* old_tail = _db.zd_sel_extpkg_tail;
        row.zd_sel_extpkg_next = NULL;
        row.zd_sel_extpkg_prev = old_tail;
        _db.zd_sel_extpkg_tail = &row;
        ainst::FExtpkg **new_row_a = &old_tail->zd_sel_extpkg_next;
        ainst::FExtpkg **new_row_b = &_db.zd_sel_extpkg_head;
        ainst::FExtpkg **new_row = old_tail ? new_row_a : new_row_b;
        *new_row = &row;
        _db.zd_sel_extpkg_n++;
    }
}

// --- ainst.FDb.zd_sel_extpkg.Remove
// Remove element from index. If element is not in index, do nothing.
void ainst::zd_sel_extpkg_Remove(ainst::FExtpkg& row) {
    if (zd_sel_extpkg_InLlistQ(row)) {
        ainst::FExtpkg* old_head       = _db.zd_sel_extpkg_head;
        (void)old_head; // in case it's not used
        ainst::FExtpkg* prev = row.zd_sel_extpkg_prev;
        ainst::FExtpkg* next = row.zd_sel_extpkg_next;
        // if element is first, adjust list head; otherwise, adjust previous element's next
        ainst::FExtpkg **new_next_a = &prev->zd_sel_extpkg_next;
        ainst::FExtpkg **new_next_b = &_db.zd_sel_extpkg_head;
        ainst::FExtpkg **new_next = prev ? new_next_a : new_next_b;
        *new_next = next;
        // if element is last, adjust list tail; otherwise, adjust next element's prev
        ainst::FExtpkg **new_prev_a = &next->zd_sel_extpkg_prev;
        ainst::FExtpkg **new_prev_b = &_db.zd_sel_extpkg_tail;
        ainst::FExtpkg **new_prev = next ? new_prev_a : new_prev_b;
        *new_prev = prev;
        _db.zd_sel_extpkg_n--;
        row.zd_sel_extpkg_next=(ainst::FExtpkg*)-1; // not-in-list
    }
}

// --- ainst.FDb.zd_sel_extpkg.RemoveAll
// Empty the index. (The rows are not deleted)
void ainst::zd_sel_extpkg_RemoveAll() {
    ainst::FExtpkg* row = _db.zd_sel_extpkg_head;
    _db.zd_sel_extpkg_head = NULL;
    _db.zd_sel_extpkg_tail = NULL;
    _db.zd_sel_extpkg_n = 0;
    while (row) {
        ainst::FExtpkg* row_next = row->zd_sel_extpkg_next;
        row->zd_sel_extpkg_next  = (ainst::FExtpkg*)-1;
        row->zd_sel_extpkg_prev  = NULL;
        row = row_next;
    }
}

// --- ainst.FDb.zd_sel_extpkg.RemoveFirst
// If linked list is empty, return NULL. Otherwise unlink and return pointer to first element.
ainst::FExtpkg* ainst::zd_sel_extpkg_RemoveFirst() {
    ainst::FExtpkg *row = NULL;
    row = _db.zd_sel_extpkg_head;
    if (row) {
        ainst::FExtpkg *next = row->zd_sel_extpkg_next;
        _db.zd_sel_extpkg_head = next;
        ainst::FExtpkg **new_end_a = &next->zd_sel_extpkg_prev;
        ainst::FExtpkg **new_end_b = &_db.zd_sel_extpkg_tail;
        ainst::FExtpkg **new_end = next ? new_end_a : new_end_b;
        *new_end = NULL;
        _db.zd_sel_extpkg_n--;
        row->zd_sel_extpkg_next = (ainst::FExtpkg*)-1; // mark as not-in-list
    }
    return row;
}

// --- ainst.FDb.zd_sel_extpkg.InsertBefore
// Insert row before given element, or at tail when before is NULL; no-op if row is already in list.
void ainst::zd_sel_extpkg_InsertBefore(ainst::FExtpkg& row, ainst::FExtpkg* before) {
    if (!zd_sel_extpkg_InLlistQ(row) && &row != before) {
        ainst::FExtpkg* next = before;
        ainst::FExtpkg* prev = next ? next->zd_sel_extpkg_prev : _db.zd_sel_extpkg_tail;
        row.zd_sel_extpkg_next = next;
        row.zd_sel_extpkg_prev = prev;
        ainst::FExtpkg **prev_link_a = &prev->zd_sel_extpkg_next;
        ainst::FExtpkg **prev_link_b = &_db.zd_sel_extpkg_head;
        *(prev ? prev_link_a : prev_link_b) = &row;
        ainst::FExtpkg **next_link_a = &next->zd_sel_extpkg_prev;
        ainst::FExtpkg **next_link_b = &_db.zd_sel_extpkg_tail;
        *(next ? next_link_a : next_link_b) = &row;
        _db.zd_sel_extpkg_n++;
    }
}

