// --- ainst.FDb.ind_extpkgver.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool ainst::ind_extpkgver_InsertMaybe(ainst::FExtpkgver& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_extpkgver_next == (ainst::FExtpkgver*)-1)) {// check if in hash already
        row.ind_extpkgver_hashval = algo::Smallstr50_Hash(0, row.extpkg);
        ind_extpkgver_Reserve(1);
        u32 index = row.ind_extpkgver_hashval & (_db.ind_extpkgver_buckets_n - 1);
        ainst::FExtpkgver* *prev = &_db.ind_extpkgver_buckets_elems[index];
        do {
            ainst::FExtpkgver* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).extpkg == row.extpkg) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_extpkgver_next;
        } while (true);
        if (retval) {
            row.ind_extpkgver_next = *prev;
            _db.ind_extpkgver_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- ainst.FDb.ind_extpkgver.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void ainst::ind_extpkgver_Remove(ainst::FExtpkgver& row) {
    if (LIKELY(row.ind_extpkgver_next != (ainst::FExtpkgver*)-1)) {// check if in hash already
        u32 index = row.ind_extpkgver_hashval & (_db.ind_extpkgver_buckets_n - 1);
        ainst::FExtpkgver* *prev = &_db.ind_extpkgver_buckets_elems[index]; // addr of pointer to current element
        while (ainst::FExtpkgver *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_extpkgver_next; // unlink (singly linked list)
                _db.ind_extpkgver_n--;
                row.ind_extpkgver_next = (ainst::FExtpkgver*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_extpkgver_next;
        }
    }
}

// --- ainst.FDb.ind_extpkgver.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void ainst::ind_extpkgver_Reserve(int n) {
    ind_extpkgver_AbsReserve(_db.ind_extpkgver_n + n);
}

// --- ainst.FDb.ind_extpkgver.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void ainst::ind_extpkgver_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_extpkgver_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(ainst::FExtpkgver*);
        u32 new_size = new_nbuckets * sizeof(ainst::FExtpkgver*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        ainst::FExtpkgver* *new_buckets = (ainst::FExtpkgver**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("ainst.out_of_memory  field:ainst.FDb.ind_extpkgver");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_extpkgver_buckets_n; i++) {
            ainst::FExtpkgver* elem = _db.ind_extpkgver_buckets_elems[i];
            while (elem) {
                ainst::FExtpkgver &row        = *elem;
                ainst::FExtpkgver* next       = row.ind_extpkgver_next;
                u32 index          = row.ind_extpkgver_hashval & (new_nbuckets-1);
                row.ind_extpkgver_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_extpkgver_buckets_elems, old_size);
        _db.ind_extpkgver_buckets_elems = new_buckets;
        _db.ind_extpkgver_buckets_n = new_nbuckets;
    }
}

// --- ainst.FDb.upstreamtype.Alloc
// Allocate memory for new default row.
// If out of memory, process is killed.
ainst::FUpstreamtype& ainst::upstreamtype_Alloc() {
    ainst::FUpstreamtype* row = upstreamtype_AllocMaybe();
    if (UNLIKELY(row == NULL)) {
        FatalErrorExit("ainst.out_of_mem  field:ainst.FDb.upstreamtype  comment:'Alloc failed'");
    }
    return *row;
}

// --- ainst.FDb.upstreamtype.AllocMaybe
// Allocate memory for new element. If out of memory, return NULL.
ainst::FUpstreamtype* ainst::upstreamtype_AllocMaybe() {
    ainst::FUpstreamtype *row = (ainst::FUpstreamtype*)upstreamtype_AllocMem();
    if (row) {
        new (row) ainst::FUpstreamtype; // call constructor
    }
    return row;
}

// --- ainst.FDb.upstreamtype.InsertMaybe
// Create new row from struct.
// Return pointer to new element, or NULL if insertion failed (due to out-of-memory, duplicate key, etc)
ainst::FUpstreamtype* ainst::upstreamtype_InsertMaybe(const dev::Upstreamtype &value) {
    ainst::FUpstreamtype *row = &upstreamtype_Alloc(); // if out of memory, process dies. if input error, return NULL.
    upstreamtype_CopyIn(*row,const_cast<dev::Upstreamtype&>(value));
    bool ok = upstreamtype_XrefMaybe(*row); // this may return false
    if (!ok) {
        upstreamtype_RemoveLast(); // delete offending row, any existing xrefs are cleared
        row = NULL; // forget this ever happened
    }
    return row;
}

// --- ainst.FDb.upstreamtype.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* ainst::upstreamtype_AllocMem() {
    u64 new_nelems     = _db.upstreamtype_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    ainst::FUpstreamtype*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.upstreamtype_lary[bsr];
        if (!lev) {
            lev=(ainst::FUpstreamtype*)algo_lib::malloc_AllocMem(sizeof(ainst::FUpstreamtype) * (u64(1)<<bsr));
            _db.upstreamtype_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.upstreamtype_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- ainst.FDb.upstreamtype.RemoveAll
// Remove all elements from Lary
void ainst::upstreamtype_RemoveAll() {
    for (u64 n = _db.upstreamtype_n; n>0; ) {
        n--;
        upstreamtype_qFind(u64(n)).~FUpstreamtype(); // destroy last element
        _db.upstreamtype_n = i64(n);
    }
}

// --- ainst.FDb.upstreamtype.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void ainst::upstreamtype_RemoveLast() {
    u64 n = _db.upstreamtype_n;
    if (n > 0) {
        n -= 1;
        upstreamtype_qFind(u64(n)).~FUpstreamtype();
        _db.upstreamtype_n = i64(n);
    }
}

// --- ainst.FDb.upstreamtype.LoadStatic
static void ainst::upstreamtype_LoadStatic() {
    static struct _t {
        const char *s;
        void (*step)(ainst::FExtpkg&);
    } data[] = {
        { "dev.upstreamtype  upstreamtype:github  comment:\"github releases, then tags; locator is <owner>/<repo>\"", ainst::upstreamtype_github }
        ,{NULL, NULL}
    };
    (void)data;
    for (int i=0; data[i].s; i++) {
        dev::Upstreamtype upstreamtype;
        (void)dev::Upstreamtype_ReadStrptrMaybe(upstreamtype, algo::strptr(data[i].s));
        ainst::FUpstreamtype *elem = upstreamtype_InsertMaybe(upstreamtype);
        vrfy(elem, tempstr("ainst.static_insert_fatal_error")
        << Keyval("tuple",algo::strptr(data[i].s))
        << Keyval("comment",algo_lib::DetachBadTags()));
        elem->step = data[i].step;
    }
}

// --- ainst.FDb.upstreamtype.XrefMaybe
// Insert row into all appropriate indices. If error occurs, store error
// in algo_lib::_db.errtext and return false. Caller must Delete or Unref such row.
bool ainst::upstreamtype_XrefMaybe(ainst::FUpstreamtype &row) {
    bool retval = true;
    (void)row;
    // insert upstreamtype into index ind_upstreamtype
    if (true) { // user-defined insert condition
        bool success = ind_upstreamtype_InsertMaybe(row);
        if (UNLIKELY(!success)) {
            ch_RemoveAll(algo_lib::_db.errtext);
            algo_lib::_db.errtext << "ainst.duplicate_key  xref:ainst.FDb.ind_upstreamtype"; // check for duplicate key
            return false;
        }
    }
    return retval;
}

