// --- ainst.FExtpkg.zd_extpkgsrc.Insert
// Insert row into linked list. If row is already in linked list, do nothing.
void ainst::zd_extpkgsrc_Insert(ainst::FExtpkg& parent, ainst::FExtpkgsrc& row) {
    if (!extpkg_zd_extpkgsrc_InLlistQ(row)) {
        ainst::FExtpkgsrc* old_tail = parent.zd_extpkgsrc_tail;
        row.extpkg_zd_extpkgsrc_next = NULL;
        row.extpkg_zd_extpkgsrc_prev = old_tail;
        parent.zd_extpkgsrc_tail = &row;
        ainst::FExtpkgsrc **new_row_a = &old_tail->extpkg_zd_extpkgsrc_next;
        ainst::FExtpkgsrc **new_row_b = &parent.zd_extpkgsrc_head;
        ainst::FExtpkgsrc **new_row = old_tail ? new_row_a : new_row_b;
        *new_row = &row;
        parent.zd_extpkgsrc_n++;
    }
}

// --- ainst.FExtpkg.zd_extpkgsrc.Remove
// Remove element from index. If element is not in index, do nothing.
void ainst::zd_extpkgsrc_Remove(ainst::FExtpkg& parent, ainst::FExtpkgsrc& row) {
    if (extpkg_zd_extpkgsrc_InLlistQ(row)) {
        ainst::FExtpkgsrc* old_head       = parent.zd_extpkgsrc_head;
        (void)old_head; // in case it's not used
        ainst::FExtpkgsrc* prev = row.extpkg_zd_extpkgsrc_prev;
        ainst::FExtpkgsrc* next = row.extpkg_zd_extpkgsrc_next;
        // if element is first, adjust list head; otherwise, adjust previous element's next
        ainst::FExtpkgsrc **new_next_a = &prev->extpkg_zd_extpkgsrc_next;
        ainst::FExtpkgsrc **new_next_b = &parent.zd_extpkgsrc_head;
        ainst::FExtpkgsrc **new_next = prev ? new_next_a : new_next_b;
        *new_next = next;
        // if element is last, adjust list tail; otherwise, adjust next element's prev
        ainst::FExtpkgsrc **new_prev_a = &next->extpkg_zd_extpkgsrc_prev;
        ainst::FExtpkgsrc **new_prev_b = &parent.zd_extpkgsrc_tail;
        ainst::FExtpkgsrc **new_prev = next ? new_prev_a : new_prev_b;
        *new_prev = prev;
        parent.zd_extpkgsrc_n--;
        row.extpkg_zd_extpkgsrc_next=(ainst::FExtpkgsrc*)-1; // not-in-list
    }
}

// --- ainst.FExtpkg.zd_extpkgsrc.RemoveAll
// Empty the index. (The rows are not deleted)
void ainst::zd_extpkgsrc_RemoveAll(ainst::FExtpkg& parent) {
    ainst::FExtpkgsrc* row = parent.zd_extpkgsrc_head;
    parent.zd_extpkgsrc_head = NULL;
    parent.zd_extpkgsrc_tail = NULL;
    parent.zd_extpkgsrc_n = 0;
    while (row) {
        ainst::FExtpkgsrc* row_next = row->extpkg_zd_extpkgsrc_next;
        row->extpkg_zd_extpkgsrc_next  = (ainst::FExtpkgsrc*)-1;
        row->extpkg_zd_extpkgsrc_prev  = NULL;
        row = row_next;
    }
}

// --- ainst.FExtpkg.zd_extpkgsrc.RemoveFirst
// If linked list is empty, return NULL. Otherwise unlink and return pointer to first element.
ainst::FExtpkgsrc* ainst::zd_extpkgsrc_RemoveFirst(ainst::FExtpkg& parent) {
    ainst::FExtpkgsrc *row = NULL;
    row = parent.zd_extpkgsrc_head;
    if (row) {
        ainst::FExtpkgsrc *next = row->extpkg_zd_extpkgsrc_next;
        parent.zd_extpkgsrc_head = next;
        ainst::FExtpkgsrc **new_end_a = &next->extpkg_zd_extpkgsrc_prev;
        ainst::FExtpkgsrc **new_end_b = &parent.zd_extpkgsrc_tail;
        ainst::FExtpkgsrc **new_end = next ? new_end_a : new_end_b;
        *new_end = NULL;
        parent.zd_extpkgsrc_n--;
        row->extpkg_zd_extpkgsrc_next = (ainst::FExtpkgsrc*)-1; // mark as not-in-list
    }
    return row;
}

// --- ainst.FExtpkg.zd_extpkgsrc.InsertBefore
// Insert row before given element, or at tail when before is NULL; no-op if row is already in list.
void ainst::zd_extpkgsrc_InsertBefore(ainst::FExtpkg& parent, ainst::FExtpkgsrc& row, ainst::FExtpkgsrc* before) {
    if (!extpkg_zd_extpkgsrc_InLlistQ(row) && &row != before) {
        ainst::FExtpkgsrc* next = before;
        ainst::FExtpkgsrc* prev = next ? next->extpkg_zd_extpkgsrc_prev : parent.zd_extpkgsrc_tail;
        row.extpkg_zd_extpkgsrc_next = next;
        row.extpkg_zd_extpkgsrc_prev = prev;
        ainst::FExtpkgsrc **prev_link_a = &prev->extpkg_zd_extpkgsrc_next;
        ainst::FExtpkgsrc **prev_link_b = &parent.zd_extpkgsrc_head;
        *(prev ? prev_link_a : prev_link_b) = &row;
        ainst::FExtpkgsrc **next_link_a = &next->extpkg_zd_extpkgsrc_prev;
        ainst::FExtpkgsrc **next_link_b = &parent.zd_extpkgsrc_tail;
        *(next ? next_link_a : next_link_b) = &row;
        parent.zd_extpkgsrc_n++;
    }
}

