// --- ainst...SizeCheck
inline static void ainst::SizeCheck() {
}

// --- ainst...StaticCheck
void ainst::StaticCheck() {
    algo_assert(sizeof(ainst::extpkg_step_hook) == 8); // csize:ainst.extpkg_step_hook
    algo_assert(sizeof(ainst::upstreamtype_step_hook) == 8); // csize:ainst.upstreamtype_step_hook
    algo_assert(_offset_of(ainst::FieldId, value) + sizeof(((ainst::FieldId*)0)->value) == sizeof(ainst::FieldId));
}

// --- ainst...main
int main(int argc, char **argv) {
    try {
        algo_lib::FDb_Init();
        lib_curl::FDb_Init();
        lib_json::FDb_Init();
        ainst::FDb_Init();
        algo_lib::_db.argc = argc;
        algo_lib::_db.argv = argv;
        algo_lib::IohookInit();
        algo_lib::_db.clock = algo::CurrSchedTime(); // initialize clock
        ainst::ReadArgv(); // dmmeta.main:ainst
        ainst::Main(); // user-defined main
    } catch(algo_lib::ErrorX &x) {
        prerr("ainst.error  " << x); // there may be additional hints in DetachBadTags
        algo_lib::_db.exit_code = 1;
    }
    if (algo_lib::_db.last_signal) {
        algo_lib::_db.exit_code = 1;
    }
    try {
        ainst::FDb_Uninit();
        lib_json::FDb_Uninit();
        lib_curl::FDb_Uninit();
        algo_lib::FDb_Uninit();
    } catch(algo_lib::ErrorX &) {
        // don't print anything, might crash
        algo_lib::_db.exit_code = 1;
    }
    // only the lower 1 byte makes it to the outside world
    (void)i32_UpdateMin(algo_lib::_db.exit_code,255);
    return algo_lib::_db.exit_code;
}

